package io.atlas.modules.research.menu;
import io.atlas.modules.research.model.ResearchPlan;
import io.atlas.modules.research.repository.ResearchRepository.Summary;
import io.atlas.modules.research.ResearchModule;
import net.minecraft.world.inventory.*;import net.minecraft.world.entity.player.*;import net.minecraft.world.item.*;import net.minecraft.world.item.component.ItemLore;import net.minecraft.world.SimpleContainer;import net.minecraft.core.component.DataComponents;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerPlayer;import java.util.*;
public final class ResearchMenu extends ChestMenu {
 private final Summary summary;private final String track;private boolean used;
 public ResearchMenu(int id,Inventory inventory,Summary summary,String track){super(MenuType.GENERIC_9x3,id,inventory,contents(summary,track),3);this.summary=summary;this.track=track;}
 private static ItemStack icon(Item item,String title,String... lore){var stack=new ItemStack(item);stack.set(DataComponents.CUSTOM_NAME,Component.literal(title));stack.set(DataComponents.LORE,new ItemLore(Arrays.stream(lore).map(Component::literal).map(c->(Component)c).toList()));return stack;}
 private static SimpleContainer contents(Summary summary,String track){var c=new SimpleContainer(27);if(track==null){for(int i=0;i<3;i++){String key=ResearchPlan.TRACKS.get(i);c.setItem(11+i*2,icon(Items.BOOK,"§b"+ResearchPlan.name(key),"§fProgresso: "+summary.progress(key)+" "+ResearchPlan.objective(key),"§7Cinco etapas permanentes.","§eClique para abrir."));}c.setItem(4,icon(Items.PAPER,"§bPesquisas Pokémon","§7Capturas novas no Survival, Nether e End.","§7Seus Pokémon ficam com você.","§7Cada etapa paga uma única vez."));}else{c.setItem(4,icon(Items.BOOK,"§b"+ResearchPlan.name(track),"§f"+summary.progress(track)+" "+ResearchPlan.objective(track)));for(var stage:ResearchPlan.stages(track)){var paid=summary.payments().stream().filter(p->p.track().equals(track)&&p.stage()==stage.stage()).findFirst().orElse(null);boolean previous=stage.stage()==1||summary.payments().stream().anyMatch(p->p.track().equals(track)&&p.stage()==stage.stage()-1&&p.state().equals("PAID"));boolean available=paid==null&&previous&&summary.progress(track)>=stage.target();String state=paid==null?available?"§aDisponível — clique para resgatar":"§7Continue pesquisando":paid.state().equals("PAID")?"§7Pagamento recebido":paid.state().equals("REVIEW")?"§cAguardando conferência da staff":"§ePagamento em andamento";c.setItem(10+stage.stage(),icon(available?Items.EMERALD:paid!=null&&paid.state().equals("PAID")?Items.PAPER:Items.GRAY_DYE,"§eEtapa "+stage.stage(),"§fObjetivo: "+stage.target()+" "+ResearchPlan.objective(track),"§6Prêmio: "+stage.money()+" CobbleDollars",state));}c.setItem(18,icon(Items.ARROW,"§eVoltar"));}c.setItem(22,icon(Items.CLOCK,"§eAtualizar"));return c;}
 @Override public void clicked(int slot,int button,ClickType type,Player player){if(!(player instanceof ServerPlayer p)||type!=ClickType.PICKUP||used)return;if(slot==22){used=true;ResearchModule.service().open(p,track);return;}if(track==null){for(int i=0;i<3;i++)if(slot==11+i*2){used=true;ResearchModule.service().open(p,ResearchPlan.TRACKS.get(i));return;}}else{if(slot==18){used=true;ResearchModule.service().open(p,null);return;}if(slot>=11&&slot<=15){int stage=slot-10;boolean previous=stage==1||summary.payments().stream().anyMatch(r->r.track().equals(track)&&r.stage()==stage-1&&r.state().equals("PAID"));if(!previous||summary.progress(track)<ResearchPlan.stage(track,stage).target()||summary.payments().stream().anyMatch(r->r.track().equals(track)&&r.stage()==stage))return;used=true;ResearchModule.service().claim(p,track,stage);}}}
 @Override public ItemStack quickMoveStack(Player player,int slot){return ItemStack.EMPTY;}
}
